package com.subin.controller;
import java.util.List;

import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseBody;

import com.subin.service.SelectService;
import com.subin.vo.Board;

@Controller
public class controller {
   @RequestMapping("/")
   public String App() {
      return "index";
   }
   @Autowired
   SelectService ssv;


   @GetMapping("/back")
   public String  back(HttpServletRequest rq, Model model, HttpServletResponse rs) throws Exception {
      System.out.println("안녕하세요"+rq.getParameter("Name")+"님");
      model.addAttribute("board", ssv.find());
      model.addAttribute("test", "안녕");
      return "index";


   }
   @ResponseBody
   @RequestMapping("/insert")
   public String insert(HttpServletRequest rq, HttpServletResponse rs) throws Exception {
      rq.setCharacterEncoding("euc-kr");
   String name   = rq.getParameter("Name");
   String story =rq.getParameter("story");
   String maker = rq.getParameter("maker");
   Board board = new Board();
   board.setName(name);
   board.setStory(story);
   board.setMaker(maker);
   System.out.println(board.getStory());
   ssv.insert(board);
   rs.sendRedirect("index.html");
   return "success!";
   }

}

