		this.x = x;
		this.y = y;
	}

	public void setTest(TestIns testIns) {
		testIns = new TestIns(30, 40);
		System.out.println(testIns.hashCode());
		System.out.println(this.hashCode());
	}

	@Override
	public String toString() {

		return "x : " + x + ", y :" + y;
	}
}

